import assert from 'assert';
import bundle from '../src/bundle';
import fs from 'fs';
import path from 'path';
import eventToPromise from 'event-to-promise';

import {exec} from 'mz/child_process';

suite('bundle', function() {
  suite('simple fixture', function() {
    let dir = path.join(__dirname, 'fixtures/a/');

    test('bundle', async () => {
      let fixturePkg = require(path.join(dir, 'package.json'));
      await exec('rm -rf node_modules.tar', { cwd: dir });
      await exec('rm -rf node_modules', { cwd: dir });
      await exec('npm i', { cwd: dir });
      let stream = bundle(fixturePkg, dir);
      let dest = path.join(dir, 'node_modules.tar');
      let writer = fs.createWriteStream(dest);
      stream.pipe(writer);
      await eventToPromise(writer, 'finish');

      // Now expand now modules again...
      await exec(`cat node_modules.tar | tar -x`, { cwd: dir });
      let [mainOutput] = await exec(`node ${dir}`);
      assert(mainOutput);
      assert(mainOutput.indexOf('-') !== -1);
    });
  });

});
